package bo.com.ganadero.alertas.application;
import bo.com.ganadero.alertas.domain.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.*;import java.time.format.DateTimeFormatter;import java.util.*;
@Service public class MotorAlertasService implements MotorAlertas{private final AlertaRepository repo;public MotorAlertasService(AlertaRepository r){repo=r;}
 @Transactional public UUID programar(ProgramarAlertaCommand c){Map<String,Object> md=c.metadata()==null?new HashMap<>():new HashMap<>(c.metadata());Instant vencimiento=instant(md.remove("fechaVencimiento"));Plantilla p=plantilla(c.tipo(),c.animalId(),vencimiento==null?c.fechaProgramada():vencimiento);Alerta a=new Alerta(UUID.randomUUID(),c.empresaId(),c.animalId(),c.tipo(),p.titulo,p.mensaje,p.severidad,c.fechaProgramada(),vencimiento,c.origenTipo(),c.origenId(),EstadoAlerta.PROGRAMADA,md,null,null,null,null,null,null,null,0,null,null,null);return repo.programar(a).id();}
 @Transactional public void cancelarPorOrigen(UUID e,String o,UUID id,String motivo){if(id!=null)repo.cancelarOrigen(e,o,id,motivo);}@Transactional public void resolverPorOrigen(UUID e,String o,UUID id){if(id!=null)repo.resolverOrigen(e,o,id,null);}
 private Instant instant(Object v){try{return v==null?null:Instant.parse(v.toString());}catch(Exception e){return null;}}private Plantilla plantilla(TipoAlerta t,UUID animal,Instant fecha){String f=DateTimeFormatter.ofPattern("dd/MM/yyyy HH:mm").withZone(ZoneId.of("America/La_Paz")).format(fecha);return switch(t){case VACUNACION_PROXIMA->new Plantilla("Vacunacion proxima","El animal tiene una vacunacion prevista para "+f,SeveridadAlerta.WARNING);case DIAGNOSTICO_GESTACION_PENDIENTE->new Plantilla("Diagnostico de gestacion pendiente","Corresponde realizar el diagnostico de gestacion el "+f,SeveridadAlerta.WARNING);case PROXIMO_PARTO->new Plantilla("Parto proximo","El parto esta previsto para "+f,SeveridadAlerta.WARNING);case DESTETE_PROXIMO->new Plantilla("Destete proximo","El destete esta previsto para "+f,SeveridadAlerta.INFO);case TRATAMIENTO_PENDIENTE->new Plantilla("Tratamiento pendiente","Existe una aplicacion programada para "+f,SeveridadAlerta.URGENTE);case TRATAMIENTO_ATRASADO->new Plantilla("Tratamiento atrasado","Una aplicacion programada continua pendiente",SeveridadAlerta.URGENTE);case CASO_CLINICO_CRITICO->new Plantilla("Caso clinico critico","Se registro un caso clinico critico que requiere atencion inmediata",SeveridadAlerta.CRITICA);case RETIRO_SANITARIO->new Plantilla("Retiro sanitario","Finaliza un periodo de retiro sanitario el "+f,SeveridadAlerta.WARNING);case CUARENTENA_POR_FINALIZAR->new Plantilla("Cuarentena por finalizar","La cuarentena finaliza el "+f,SeveridadAlerta.WARNING);};}private record Plantilla(String titulo,String mensaje,SeveridadAlerta severidad){}
}
